import { describe, expect, it } from 'vitest';
import { NUMBER_SUPPORT_GOLDEN } from '../generated/number-support-golden';
import { mockNumberSupport } from './widgets';

/** The mock imitates the engine's `number_support`; these are the engine's own values (generated by its test). */
describe('the mock number support', () => {
  it.each([
    ['macos', 18, 'mac'],
    ['windows', 16, 'win16'],
    ['windows', 20, 'win20'],
    ['windows', 24, 'win24'],
  ] as const)('%s at %i px says what the engine says', (os, px, key) => {
    expect(mockNumberSupport(os, px)).toEqual(NUMBER_SUPPORT_GOLDEN[key]);
  });
});
